import '../../../core/engine/models/property_health_result.dart';
import '../../../models/property_health/recommendation.dart';
import '../models/dashboard_priority.dart';

/// Converts Property Health Engine recommendations into
/// dashboard-ready priorities.
///
/// The mapper deliberately does not introduce a new scoring model.
/// It preserves the recommendation priority and estimated PHI gain
/// generated by the Property Health Engine.
class DashboardPriorityMapper {
  const DashboardPriorityMapper();

  List<DashboardPriority> map(
    PropertyHealthResult? healthResult,
  ) {
    if (healthResult == null ||
        healthResult.recommendations.isEmpty) {
      return const [];
    }

    final priorities = healthResult.recommendations
        .map(_mapRecommendation)
        .toList();

    priorities.sort(_comparePriorities);

    return List.unmodifiable(priorities);
  }

  DashboardPriority _mapRecommendation(
    Recommendation recommendation,
  ) {
    return DashboardPriority(
      id: recommendation.id,
      title: recommendation.title,
      description: recommendation.description,
      priority: recommendation.priority,
      estimatedPHIGain: recommendation.estimatedPHIGain,
      requiredDocuments: List.unmodifiable(
        recommendation.requiredDocuments,
      ),
    );
  }

  int _comparePriorities(
    DashboardPriority first,
    DashboardPriority second,
  ) {
    final priorityComparison =
        first.priorityRank.compareTo(second.priorityRank);

    if (priorityComparison != 0) {
      return priorityComparison;
    }

    final gainComparison =
        second.estimatedPHIGain.compareTo(
      first.estimatedPHIGain,
    );

    if (gainComparison != 0) {
      return gainComparison;
    }

    return first.title.compareTo(second.title);
  }
}